// Arma una llamada eth_call por cada dato que queremos del token. Cada ítem que sale de acá
// es un pedido: el HTTP Request siguiente se ejecuta una vez por ítem.
//
// «data» es la llamada codificada con la ABI: 4 bytes que dicen qué función (el selector) y
// después los parámetros, cada uno rellenado con ceros hasta 32 bytes (64 caracteres hex).
// El selector son los primeros 4 bytes del keccak256 de la firma: keccak256("decimals()") = 0x313ce567...
const config = $input.first().json;
const token = String(config.token || '').trim().toLowerCase();
const wallet = String(config.wallet || '').trim().toLowerCase();
for (const [campo, valor] of [['token', token], ['wallet', wallet]]) {
  if (!/^0x[0-9a-f]{40}$/.test(valor)) throw new Error(`En «Token y wallet», ${campo} tiene que ser 0x y 40 caracteres hexadecimales.`);
}

const SELECTORES = {
  nombre: '0x06fdde03', // name()
  simbolo: '0x95d89b41', // symbol()
  decimales: '0x313ce567', // decimals()
  saldo: '0x70a08231', // balanceOf(address)
};
// balanceOf recibe una dirección: se le saca el 0x y se rellena con ceros a la izquierda.
const parametroWallet = wallet.slice(2).padStart(64, '0');

return [
  { json: { campo: 'nombre', to: token, data: SELECTORES.nombre } },
  { json: { campo: 'simbolo', to: token, data: SELECTORES.simbolo } },
  { json: { campo: 'decimales', to: token, data: SELECTORES.decimales } },
  { json: { campo: 'saldo', to: token, data: SELECTORES.saldo + parametroWallet } },
];

// Decodifica las cuatro respuestas. El HTTP Request devuelve un ítem por pedido, en el mismo orden,
// así que la respuesta i corresponde a la llamada i de «Armar las llamadas».
const config = $('Token y wallet').first().json;
const llamadas = $('Armar las llamadas').all();
const r = {};
$input.all().forEach((item, i) => {
  const campo = llamadas[i].json.campo;
  if (item.json.error) throw new Error(`eth_call de ${campo} falló: ${item.json.error.message ?? JSON.stringify(item.json.error)}`);
  if (!item.json.result || item.json.result === '0x') {
    throw new Error(`${campo} volvió vacío (0x): esa dirección no tiene un contrato ERC-20 en Fuji o no tiene esa función.`);
  }
  r[campo] = item.json.result;
});

// Un número de la ABI ocupa 32 bytes: con BigInt se lee tal cual, aunque sea enorme.
const numero = (hex) => BigInt(hex);

// Un texto de la ABI viene en tres partes de 32 bytes: dónde empieza, cuántos bytes tiene y los bytes.
// Algunos tokens viejos devuelven el símbolo como bytes32 (una sola parte, rellena con ceros).
function texto(hex) {
  const d = hex.slice(2);
  if (d.length === 64) return Buffer.from(d, 'hex').toString('utf8').replace(/\u0000+$/, '');
  const inicio = Number(BigInt('0x' + d.slice(0, 64))) * 2;
  const largo = Number(BigInt('0x' + d.slice(inicio, inicio + 64)));
  return Buffer.from(d.slice(inicio + 64, inicio + 64 + largo * 2), 'hex').toString('utf8');
}

// El saldo viene en la unidad más chica del token: se divide por 10^decimales sin perder precisión.
function conDecimales(valor, decimales) {
  if (decimales === 0) return valor.toString();
  const base = 10n ** BigInt(decimales);
  const resto = (valor % base).toString().padStart(decimales, '0').replace(/0+$/, '');
  return resto ? `${valor / base}.${resto}` : `${valor / base}`;
}

const decimales = Number(numero(r.decimales));
const saldoCrudo = numero(r.saldo);
const token = String(config.token).trim().toLowerCase();
const wallet = String(config.wallet).trim().toLowerCase();

return [
  {
    json: {
      token,
      nombre: texto(r.nombre),
      simbolo: texto(r.simbolo),
      decimales,
      wallet,
      saldo: conDecimales(saldoCrudo, decimales),
      saldoCrudo: saldoCrudo.toString(),
      exploradorToken: `https://build.avax.network/explorer/fuji/c-chain/address/${token}`,
      exploradorWallet: `https://build.avax.network/explorer/fuji/c-chain/address/${wallet}`,
    },
  },
];
